const rows = $input.all().map(i => i.json);
function parseIST(ts){const m=String(ts||'').trim().match(/^(\d{4})-(\d{1,2})-(\d{1,2})[ T](\d{1,2}):(\d{2}):(\d{2})/);if(!m)return NaN;const a=m.slice(1).map(Number);const pad=n=>String(n).padStart(2,'0');return new Date(`${a[0]}-${pad(a[1])}-${pad(a[2])}T${pad(a[3])}:${pad(a[4])}:${pad(a[5])}+05:30`).getTime();}
const now = Date.now();
const WINDOW = 180*60*1000;
const out = [];
for (const r of rows){
  // Previously skipped status==='qualified'. Now INCLUDED so returning/qualified leads whose
  // new inbound DM was dropped are recovered too. Drop detection (Detect drops) still only fires
  // when the ManyChat interaction is NEWER than our last answer, so already-answered leads are ignored.
  const luts = parseIST(r.last_update_ts || r.first_contact_ts);
  if (isNaN(luts)) continue;
  if (now - luts > WINDOW) continue;
  out.push({ ig_user_id: String(r.ig_user_id||''), ig_username: String(r.ig_username||''), status: String(r.status||'').toLowerCase(), last_update_ts: r.last_update_ts||'', last_update_ms: luts });
}
out.sort((a,b)=>b.last_update_ms - a.last_update_ms);
return out.slice(0,60).map(json=>({json}));

const results = $input.all().map(i => i.json);
const cands = $('Pick candidates').all().map(i=>i.json);
const cmap = {};
for (const c of cands) cmap[String(c.ig_user_id)] = c;
// BUFFER lowered 120s -> 30s: a follow-up dropped within ~2 min of our last reply used to be
// permanently invisible (its timestamp fell inside the old buffer). 30s still absorbs clock skew
// (we always answer a few seconds AFTER the user sends, so answered msgs have interaction <= last_update).
const BUFFER = 30*1000;
const sd = $getWorkflowStaticData('global');
sd.recovered = sd.recovered || {};
const now = Date.now();
for (const k in sd.recovered){ if (now - (sd.recovered[k].ts||0) > 24*3600*1000) delete sd.recovered[k]; }
const out = [];
for (const r of results){
  const d = r && r.data ? r.data : null;
  if (!d || !d.id) continue;
  const cand = cmap[String(d.id)];
  if (!cand) continue;
  const lastIn = d.ig_last_interaction || d.last_interaction;
  if (!lastIn) continue;
  const igMs = Date.parse(lastIn);
  if (isNaN(igMs)) continue;
  const txt = String(d.last_input_text||'').trim();
  if (!(txt && igMs > cand.last_update_ms + BUFFER)) continue;
  const led = sd.recovered[String(d.id)];
  if (led && led.lastIn === lastIn) continue;
  sd.recovered[String(d.id)] = { lastIn: lastIn, ts: now };
  out.push({ json: { ig_user_id: String(d.id), ig_username: d.ig_username||cand.ig_username, ig_fullname: String(d.name||''), message_text: txt, ig_last_interaction: lastIn, our_last_update: cand.last_update_ts } });
}
return out;
